# >>> STATIC
_static_tcp_rst() {
    cat <<-'ARGCEOF'
	pong	Count it as a successful ping: the host answered, it just isn't listening
	drop	Count it as a failed ping
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_cmd() {
    if [[ -n "$argc__option" ]]; then
        local -n ref="$argc__option"
        argc__positionals=( "${ref[@]}" )
        unset -n ref
    fi
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_color() {
    printf '%s\n' black red green yellow blue magenta cyan gray dark-gray \
        light-red light-green light-yellow light-blue light-magenta light-cyan white
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_interface() {
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
        return 0
    fi
    if [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 | sed 's|.*/||'
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}
